insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 37, 'E ficavam muito admirados, dizendo: Ele faz tudo bem! Aos surdos faz ouvir, e aos mudos falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 1, 'Naqueles dias, quando havia uma multidão muito grande, e não tinham o que comer, Jesus chamou os seus discípulos a si, e disse-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 2, 'Tenho compaixão da multidão, porque já há três dias que estão comigo, e não têm o que comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 3, 'E se eu os deixar ir sem comer para suas casas desmaiarão no caminho; porque alguns deles vieram de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 4, 'Os seus discípulos lhe responderam: De onde poderá alguém saciar estes de pão aqui no deserto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 5, '[Jesus] lhes perguntou: Quantos pães tendes? E eles disseram: Sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 6, 'Então mandou à multidão que se sentassem no chão. Em seguida, tomou os sete pães, e tendo dado graças, partiu-os, e os deu a seus discípulos, para que os pusessem diante deles. E eles os puseram diante da multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 7, 'E tinham uns poucos peixinhos, e havendo dado graças, disse que também os pusessem diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 8, 'Eles comeram, e se saciaram; e levantaram, do que sobrou dos pedaços, sete cestos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 9, 'Os que comeram eram quase quatro mil. Depois os despediu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 10, 'E logo entrou no barco com os seus discípulos, e veio para a região de Dalmanuta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 11, 'Os fariseus vieram, e começaram a disputar com ele, pedindo-lhe sinal do céu, para o testar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 12, 'E ele, suspirando profundamente em seu espírito, disse: Por que esta geração pede um sinal? Em verdade vos digo, que não se dará sinal a esta geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 13, 'Então os deixou, voltou a entrar no barco , e foi para a outro lado [do mar] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 14, 'E [os seus discípulos] haviam se esquecido de tomar pão, e nada tinham, a não ser um pão com eles no barco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 15, 'E [Jesus] lhes deu a seguinte ordem: Prestai atenção: tende cuidado com o fermento dos fariseus e o fermento de Herodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 16, 'E indagavam-se com os outros , dizendo: É porque não temos pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 17, 'Jesus soube e lhes disse: Por que indagais que não tendes pão? Não percebeis ainda, nem entendeis? Ainda tendes o vosso coração endurecido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 18, 'Tendes olhos, e não vedes? Tendes ouvidos, e não ouvis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 19, 'E não vos lembrais de, quando parti os cinco pães entre os cinco mil, quantos cestos cheios de pedaços levantastes?Responderam-lhe: Doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 20, 'E quando [parti] os sete entre os quatro mil, quantas cestas cheias de pedaços levantastes? Eles disseram: Sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 21, 'Ele lhes perguntou: Como não entendeis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 22, 'Então veio a Betsaida. E trouxeram-lhe um cego, e rogaram-lhe que o tocasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 23, 'Ele tomou o cego pela mão e o tirou para fora da aldeia. Depois cuspiu nos olhos dele e, pondo as mãos encima dele, perguntou-lhe se via alguma coisa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 24, 'Ele levantou os olhos e disse: Vejo as pessoas; pois vejo como árvores que andam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 25, 'Então [Jesus] pôs de novo as mãos sobre os seus olhos, e o fez olhar para cima . Assim ele ficou restabelecido, e passou a ver todos claramente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 26, 'Então o mandou para sua casa, dizendo: Não entres na aldeia, nem contes a ninguém da aldeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 27, 'Jesus saiu com os seus discípulos para as aldeias de Cesareia de Filipe; e no caminho perguntou a seus discípulos: Quem as pessoas dizem que eu sou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 28, 'Eles responderam: João Batista, e outros, Elias; e outros, algum dos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 29, 'E ele lhes perguntou: E vós, quem dizeis que eu sou? Pedro lhe respondeu: Tu és o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 30, 'E lhes ordenou que a ninguém dissessem aquilo dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 31, 'E começou a lhes ensinar que era necessário que o Filho do homem sofresse muito, e fosse rejeitado pelos anciãos e pelos chefes dos sacerdotes e escribas, e que fosse morto, e depois de três dias ressuscitasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 32, 'Ele dizia essa palavra abertamente. Então Pedro o tomou à parte, e começou a repreendê-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 33, 'Mas [Jesus] virou-se e, olhando para os seus discípulos, repreendeu Pedro, dizendo: Sai de diante de mim, satanás! Pois tu não compreendes as coisas de Deus, mas sim as humanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 34, 'Então chamou a si a multidão com os seus discípulos, e disse-lhes: Quem quiser vir após mim, negue a si mesmo, tome a sua cruz, e siga-me;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 35, 'pois quem quiser salvar a sua vida, a perderá; mas quem perder a sua vida por causa de mim e do Evangelho, esse a salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 36, 'Pois que proveito teria alguém, se ganhasse o mundo todo, e perdesse a sua alma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 37, 'Ou que daria alguém em resgate de sua alma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 8, 38, 'Porque todo aquele que se envergonhar de mim e de minhas palavras nesta geração adúltera e pecadora, também o Filho do homem, quando vier na glória de seu Pai com os santos anjos, envergonhar-se-á dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 1, 'E disse-lhes também: Em verdade vos digo, que há alguns dos que aqui estão, que não experimentarão a morte, até que vejam o reino de Deus vindo com poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 2, 'Seis dias depois, Jesus tomou consigo Pedro, Tiago, e João, e os levou à parte, sozinhos, para um alto monte ; e transfigurou-se diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 3, 'E suas roupas ficaram resplandescentes, muito brancas como a neve , como nenhum lavadeiro na terra seria capaz de branquear.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 4, 'E apareceu-lhes Elias com Moisés, e falavam com Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 5, 'Então Pedro disse a Jesus: Mestre, é bom para nós estarmos aqui; façamos três tendas: uma para ti, uma para Moisés, e uma para Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 6, 'Pois ele não sabia o que dizia, pois estavam assombrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 7, 'Então desceu uma nuvem, que os cobriu com a sua sombra, e veio uma voz da nuvem, que dizia: Este é meu Filho amado; a ele ouvi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 8, 'De repente, quando olharam em redor, não viram mais ninguém, a não ser só Jesus com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 9, 'Enquanto desciam do monte, [Jesus] lhes mandou que a ninguém contassem o que haviam visto, até que o Filho do homem ressuscitasse dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 10, 'E eles guardaram o caso entre si, perguntando uns aos outros o que seria aquilo de “ressuscitar dos mortos”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 11, 'Então lhe perguntaram: Por que os escribas dizem que Elias tem que vir primeiro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 12, 'E ele lhes respondeu: De fato Elias vem primeiro, e restaura todas as coisas. Então, como está escrito sobre o Filho do homem tem que sofrer muito, e ser desprezado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 13, 'Porém eu vos digo que Elias já veio, e fizeram-lhe tudo o que quiseram, como está escrito sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 14, 'E quando veio aos discípulos, ele viu uma grande multidão ao redor deles; e uns escribas estavam discutindo com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 15, 'Logo que toda a multidão o viu, ficou admirada. Então correram a ele, e o cumprimentaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 16, '[Jesus] perguntou aos escribas: O que estais discutindo com eles?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 17, 'E um da multidão respondeu: Mestre, trouxe a ti o meu filho, que tem um espírito mudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 18, 'E onde quer que o toma, faz-lhe ter convulsões, solta espuma, range os dentes, e vai ficando rígido. Eu disse aos teus discípulos que o expulsassem, mas não conseguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 19, '[Jesus] lhe respondeu: Ó geração incrédula! Até quando estarei ainda convosco? Até quando vos suportarei? Trazei-o a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 20, 'Então trouxeram-no a ele. E quando o viu, logo o espírito o fez ter uma convulsão e, caindo em terra, rolava, e espumava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 21, 'E perguntou ao seu pai: Quanto tempo há que isto lhe sobreveio? E ele lhe disse: Desde a infância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 22, 'E muitas vezes o lançou também no fogo e na água para o destruir. Mas, se podes algo, tem compaixão de nós, e ajuda-nos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 23, 'E Jesus lhe disse: Se podes crer, tudo é possível ao que crê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 24, 'Logo o pai do menino, clamando, com lágrimas, disse: Creio, Senhor! Ajuda-me na minha incredulidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 25, 'Quando Jesus viu que a multidão corria e se ajuntava, repreendeu o espírito imundo, dizendo-lhe: Espírito mudo e surdo, eu te ordeno, sai dele, e nunca mais entres nele!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 26, 'Então [o espírito] , gritando, e fazendo-o ter muita convulsão, saiu. E [o menino] ficou como morto, de maneira que muitos diziam que estava morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 27, 'Então Jesus o tomou pela mão, e o ergueu; e ele se levantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 28, 'E quando entrou em casa, seus discípulos lhe perguntaram à parte: Por que nós não conseguimos o expulsar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 29, 'E lhes respondeu: Este tipo não pode sair por coisa alguma, a não ser com oração e jejum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 30, 'Depois partiram dali, e caminharam pela Galileia. Mas [Jesus] não queria que ninguém soubesse,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 31, 'Porque ensinava a seus discípulos, e lhes dizia: O Filho do homem será entregue em mãos de homens, e o matarão; e [estando] ele morto, ressuscitará ao terceiro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 32, 'Mas eles não entendiam esta palavra, e temiam lhe perguntar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 33, 'E veio a Cafarnaum, e entrando em casa, perguntou-lhes: Que indagais entre vós pelo caminho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 34, 'Mas eles se calaram; porque eles haviam discutido uns com os outros pelo caminho, qual [deles seria] o maior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 35, 'E sentando-se ele, chamou aos doze, e disse-lhes: Se alguém quiser ser o primeiro, seja o últimos de todos, e servo de todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 36, 'E tomando um menino, ele o pôs no meio deles, e tomando-o entre seus braços, disse-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 37, 'Qualquer que em meu nome receber a um dos tais meninos, recebe a mim; e qualquer que me receber, não é a mim que recebe, mas, sim, àquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 38, 'E respondeu-lhe João, dizendo: Mestre, vimos um que em teu nome expulsava os demônios, e ele não nos segue. Então o proibimos, porque não nos segue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 39, 'Porém Jesus disse: Não o proibais; porque ninguém há que faça milagre em meu nome, e logo possa falar mal de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 40, 'Pois quem não é contra nós, é por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 41, 'Porque qualquer que vos der um copo d''água para beber em meu nome, porque sois de Cristo, em verdade vos digo, que não perderá sua recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 42, 'E qualquer que conduzir ao pecado um destes pequenos que creem em mim, melhor lhe fora que lhe pusesse ao pescoço uma grande pedra de moinho, e que fosse lançado no mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 43, 'E se a tua mão te faz pecar, corta-a; melhor te é entrar na vida mutilado, do que, tendo duas mãos, ir ao inferno, ao fogo que nunca se apaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 44, 'Onde seu verme não morre, e o fogo nunca se apaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 45, 'E se teu pé te faz pecar, corta-o; melhor te é entrar na vida manco, do que, tendo dois pés, ser lançado no inferno, no fogo que nunca se apaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 46, 'Onde seu verme não morre, e o fogo nunca se apaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 47, 'E se teu olho te faz pecar, lança-o fora; melhor te é entrar no Reino de Deus com um olho, do que, tendo dois olhos, ser lançado no fogo do inferno,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 48, 'onde seu verme não morre, e o fogo nunca se apaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 49, 'Porque cada um será salgado com fogo, e cada sacrifício será salgado com sal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 9, 50, 'O sal é bom; mas se o sal se tornar insípido, com que o temperareis? Tende sal em vós mesmos, e paz uns com os outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 1, 'E levantando-se dali, [Jesus] se foi aos limites da Judeia, por dalém do Jordão; e as multidões voltaram a se juntar a ele, e voltou a lhes ensinar, como tinha costume.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 2, 'E vindo a ele os fariseus, perguntaram-lhe se era lícito ao homem deixar a [sua] mulher, testando-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 3, 'Mas ele lhes respondeu: O que Moisés vos mandou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 4, 'E eles disseram: Moisés permitiu escrever carta de divórcio, e deixá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 5, 'E Jesus lhes respondeu: Foi pela dureza dos vossos corações que ele vos escreveu este mandamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 6, 'Porém, desde o princípio da criação, macho e fêmea Deus os fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 7, 'Por isso, deixará o homem a seu pai e a [sua] mãe, e se unirá à sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 8, 'E os dois serão uma [só] carne; assim, já não são dois, mas sim uma [só] carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 9, 'Portanto, o que Deus juntou, não separe o homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 10, 'E em casa seus discípulos voltaram a lhe perguntar sobre isto mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 11, 'E disse-lhes: Qualquer um que deixar a sua mulher, e se casar com outra, adultera contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 12, 'E se a mulher deixar o seu marido, e se casar com outro, adultera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 13, 'E lhe traziam crianças para que ele as tocasse, mas os discípulos repreendiam aos que [as] traziam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 14, 'Porém Jesus, vendo, indignou-se, e lhe disse: Deixai vir as crianças a mim, e não as impeçais; porque delas é o Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 15, 'Em verdade vos digo, que qualquer um que não receber o Reino de Deus como criança, em maneira nenhuma nele entrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 16, 'Então, tomando-as entre seus braços, e pondo as mãos sobre elas, ele as abençoou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 17, 'E quando ele saiu para caminhar, um [homem] correu até ele; e pondo-se de joelhos diante dele, perguntou-lhe: Bom Mestre, que farei para herdar a vida eterna?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 18, 'E Jesus lhe disse: Por que me chamas bom? Ninguém é bom, a não ser um: Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 19, 'Sabes os mandamentos: Não adulterarás; não matarás; não furtarás; não darás falso testemunho; não serás enganador; honra o teu pai e a [tua] mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 20, 'Porém ele lhe respondeu: Mestre, tudo isto guardei desde a minha juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 21, 'E olhando Jesus para ele, amou-o, e disse-lhe: Uma coisa te falta: vai, vende tudo quanto tens, e dá aos pobres; e terás um tesouro no céu; e vem, segue-me, toma [tua] cruz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 22, 'Mas ele, pesaroso desta palavra, foi-se triste; porque tinha muitas propriedades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 23, 'Então Jesus olhando ao redor, disse a seus discípulos: Como é difícil aos que têm riquezas entrar no Reino de Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 24, 'E os discípulos se espantaram destas suas palavras; mas Jesus, voltando a responder, disse-lhes: Filhos, como é difícil aos que confiam em riquezas entrar no Reino de Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 25, 'Mais fácil é passar um camelo pelo olho de uma agulha, do que entrar um rico no Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 26, 'E eles se espantavam ainda mais, dizendo uns para os outros: Quem, pois, poderá se salvar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 27, 'Porém, olhando Jesus para eles, disse: Para os seres humanos, é impossível; mas para Deus, não; porque para Deus tudo é possível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 28, 'E Pedro começou a lhe dizer: Eis que nós deixamos tudo, e te seguimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 29, 'Jesus respondeu: Em verdade vos digo, que não há ninguém que tenha deixado casa, ou irmãos, ou irmãs, ou pai, ou mãe, ou esposa, ou filhos, ou campos, por amor de mim e do Evangelho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 30, 'que não receba cem vezes tanto, agora neste tempo, casas, e irmãos, e irmãs, e mães, e filhos, e campos, com perseguições; e a vida eterna, no tempo que virá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 31, 'Porém muitos primeiros serão últimos, e últimos, primeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 32, 'E iam pelo caminho, subindo para Jerusalém; e Jesus ia diante deles, e espantavam-se, e seguiam-no atemorizados. E voltando a tomar consigo aos doze, começou-lhes a dizer as coisas que lhe viriam a acontecer:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 33, 'Eis que subimos a Jerusalém, e o Filho do homem será entregue aos chefes dos sacerdotes, e aos escribas; e o condenarão à morte, e o entregarão aos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 34, 'E escarnecerão dele, e o açoitarão, e cuspirão nele, e o matarão; e ao terceiro dia ressuscitará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 35, 'E vieram a ele Tiago e João, filhos de Zebedeu, dizendo: Mestre, queríamos que nos fizesses o que pedirmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 36, 'E ele lhes disse: O que quereis que eu vos faça?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 37, 'E eles lhe disseram: Concede-nos que em tua glória nos sentemos, um à tua direita, e outro à tua esquerda?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 38, 'Mas Jesus lhes disse: Não sabeis o que pedis; podeis vós beber o copo que eu bebo, e ser batizados com o batismo com que eu sou batizado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 39, 'E eles lhe disseram: Podemos. Porém Jesus lhes disse: Em verdade, o copo que eu bebo, bebereis; e com o batismo com que eu sou batizado, sereis batizados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 40, 'Mas sentar-se à minha direita, e à minha esquerda, não é meu concedê-lo, mas sim, para aqueles a quem está preparado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 41, 'E quando os dez ouviram isto, começaram a se irritar contra Tiago e João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 42, 'Mas Jesus, chamando-os a si, disse-lhes: Já sabeis que os que são vistos como governadores dos gentios, agem como senhores deles; e os grandes usam de autoridade sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 43, 'Mas entre vós não será assim; antes qualquer que entre vós quiser ser grande, será vosso servidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 44, 'E qualquer que de vós quiser ser o primeiro, será servo de todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 45, 'Porque também não veio o Filho do homem para ser servido, mas para servir, e dar sua vida em resgate por muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 46, 'E vieram a Jericó. E saindo ele, e seus discípulos, e uma grande multidão de Jericó, estava Bartimeu, um cego, filho de Timeu, sentado junto ao caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 47, 'E ouvindo que era Jesus o nazareno, começou a clamar, e a dizer: Jesus, Filho de Davi! Tem misericórdia de mim!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 48, 'E muitos o repreendiam, para que se calasse; mas ele clamava ainda mais: Filho de Davi! Tem misericórdia de mim!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 49, 'Jesus parou, e disse que o chamassem. Então chamaram ao cego, dizendo-lhe: Tem bom ânimo, levanta-te, ele está te chamando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 50, 'Então ele lançou sua capa, levantou-se, e veio a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 51, 'Jesus, lhe perguntou: Que queres que eu te faça? E o cego lhe disse: Mestre, que eu veja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 10, 52, 'Jesus lhe disse: Vai; a tua fé te salvou. E logo consegiu ver. Então seguiu Jesus pelo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 1, 'E quando se aproximaram de Jerusalém, de Betfagé, e de Betânia, junto ao monte das Oliveiras, [Jesus] enviou dois de seus discípulos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 2, 'dizendo-lhes: Ide ao vilarejo que está adiante de vós; e assim que nela entrardes, achareis um jumentinho amarrado, sobre o qual ninguém se sentou; soltai-o, e trazei-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 3, 'E se alguém vos disser: Por que fazeis isso?, dizei: O Senhor precisa dele, e logo o devolverá para cá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 4, 'Eles foram, e acharam o jumentinho amarrado à porta, do lado de fora em uma esquina, e o soltaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 5, 'E alguns dos que ali estavam lhes perguntaram: Que fazeis, soltando o jumentinho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 6, 'Eles lhes disseram como Jesus [lhes] havia mandado, e os deixaram ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 7, 'Então trouxeram o jumentinho a Jesus. Lançaram sobre ele suas roupas, e [Jesus] sentou-se sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 8, 'Muitos estendiam suas roupas pelo caminho, e outros cortavam ramos das árvores, e os espalhavam pelo caminho..'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 9, 'E os que iam adiante, e os que seguiam, clamavam: Hosana, bendito o que vem no Nome do Senhor!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 10, 'Bendito o Reino que vem no Nome do Senhor, [o Reino] do nosso pai Davi! Hosana nas alturas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 11, 'Jesus entrou em Jerusalém, e no Templo. E depois que ter visto tudo em redor, e sendo já tarde, ele saiu para Betânia com os doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 12, 'E no dia seguinte, quando saíram de Betânia, ele teve fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 13, 'E vendo de longe uma figueira que tinha folhas, [veio ver] se acharia alguma coisa nela; mas ao chegar perto dela, nada achou, a não ser folhas, pois não era o tempo de figos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 14, 'Então Jesus lhe disse: Nunca mais ninguém coma fruto de ti! E seus discípulos ouviram isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 15, 'Depois vieram a Jerusalém. E entrando Jesus no Templo, começou a expulsar os que vendiam e compravam no Templo; e revirou as mesas dos cambiadores, e as cadeiras dos que vendiam pombas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 16, 'E não consentia que ninguém levasse vaso algum pelo Templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 17, 'E ensinava, dizendo-lhes: Não está escrito: Minha casa será chamada casa de oração de todas as nações? Mas vós fizestes dela esconderijo de ladrões!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 18, 'Os escribas e os chefes dos sacerdotes ouviram isso, e buscavam uma maneira de o matar; pois o temiam, porque toda a multidão estava admirada do ensino dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 19, 'E como já era tarde, [Jesus] saiu fora da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 20, 'E passando pela manhã, viram que a figueira estava seca desde as raízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 21, 'Pedro se lembrou disso, e disse-lhe: Mestre, eis que a figueira que amaldiçoaste, se secou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 22, 'E respondendo Jesus, disse-lhes: Tende fé em Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 23, 'Porque em verdade vos digo que qualquer um que disser a este monte: Levanta-te, e lança-te no mar; e não duvidar em seu coração, mas crer que se fará o que diz, tudo o que disser lhe será feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 24, 'Portanto eu vos digo que tudo o que pedirdes orando, crede que recebereis, e vós [o] tereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 25, 'E quando estiverdes orando, perdoai, se tendes algo contra alguém, para que o vosso Pai, que [está] nos céus, vos perdoe vossas ofensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 26, 'Mas se vós não perdoardes, também o vosso Pai, que [está] nos céus, não vos perdoará vossas ofensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 27, 'Depois voltaram a Jerusalém; e, enquanto ele andava pelo Templo, vieram a ele os chefes dos sacerdotes, os escribas, e os anciãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 28, 'E disseram-lhe: Com que autoridade fazes estas coisas? E quem te deu esta autoridade, para fazerdes estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 29, 'Jesus lhes respondeu: Também eu vos farei uma pergunta, e respondei-me; então vos direi com que autoridade faço estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 30, 'O batismo de João era do céu ou dos homens? Respondei-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 31, 'E eles argumentavam entre si, dizendo: Se dissermos do céu, ele dirá: Por que, pois, não crestes nele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 32, 'Porém, se dissermos dos homens, tememos ao povo, porque todos consideravam que João era verdadeiramente profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 11, 33, 'Então responderam a Jesus: Não sabemos. E Jesus lhes replicou: Também eu não vos direi com que autoridade faço estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 1, 'Então [Jesus] começou a lhes dizer por parábolas: Um homem plantou uma vinha, cercou-a, fundou [nela] uma prensa de uvas, edificou uma torre, e a arrendou a uns lavradores; e partiu-se daquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 2, 'E, quando chegou o tempo, mandou um servo aos lavradores, para que recebesse dos lavradores do fruto da vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 3, 'Mas eles, tomando-o à força, feriram-no, e mandaram-no vazio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 4, 'E voltou a lhes mandar outro servo; e eles, apedrejando-o, feriram-no na cabeça e voltaram a mandá-lo maltratado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 5, 'E voltou a mandar outro, ao qual mataram, e [mandou] muitos outros, e a uns feriram, e a outros mataram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 6, 'Tendo ele, pois, ainda um, o seu filho amado, mandou-lhes também por último a este, dizendo: Pelo menos respeitarão o meu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 7, 'Mas aqueles lavradores disseram entre si: Este é o herdeiro; vinde, e o matemos; então a herança será nossa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 8, 'E pegando dele, mataram[-no] , e lançaram[-no] fora da vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 9, 'Que, pois, o senhor da vinha fará? Ele virá, destruirá aos lavradores, e dará a vinha a outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 10, 'Acaso ainda não lestes esta escritura: “A pedra que os edificadores rejeitaram, esta foi feita por cabeça de esquina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 11, 'Pelo Senhor foi feito isto, e é maravilhoso em nossos olhos”?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 12, 'E buscavam prendê-lo, mas temiam a multidão; porque entendiam que era contra eles que dizia aquela parábola; então o deixaram e se retiraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 13, 'E mandaram-lhe alguns dos fariseus e dos herodianos, para que o apanhassem em [alguma] palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 14, 'Eles se aproximaram e lhe disseram: Mestre, sabemos que és homem de verdade, e não te interessa [agradar] a ninguém, porque não te importas com a aparência humana, mas com verdade ensinas o caminho de Deus. É lícito pagar tributo a César, ou não? Devemos pagar, ou não devemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 15, 'E ele, entendendo a hipocrisia deles, disse-lhes: Por que estais me tentando? Trazei-me uma moeda, para que eu a veja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 16, 'E trouxeram. E perguntou-lhes: De quem é esta imagem, e a inscrição? E eles lhe disseram: De César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 17, 'Então Jesus, lhes respondeu: Dai, pois, a César o que é de César, e a Deus o que é de Deus. E admiram-se dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 18, 'E vieram a ele os saduceus, que dizem não haver ressurreição, e perguntaram-lhe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 19, 'Mestre, Moisés nos escreveu que, se o irmão de alguém morresse, e deixasse mulher, mas não filhos, que seu irmão se casasse com a viúva , e gerasse descendência ao seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 20, 'Houve, pois, sete irmãos, e o primeiro casou-se com a mulher, e morrendo, não deixou descendente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 21, 'Casou-se com ela também o segundo, e morreu; e nem este deixou descendente; e o terceiro da mesma maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 22, 'Os sete casaram-se com ela, mas não deixaram descendente. Finalmente, depois de todos, morreu também a mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 23, 'Na ressurreição, pois, quando ressuscitarem, ela será a mulher de qual deles? Porque os sete a tiveram por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 24, 'E Jesus lhes respondeu: Acaso não é por isso que errais, por não conhecerdes as Escrituras, nem o poder de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 25, 'Pois, quando ressuscitarem dos mortos, nem se casarão, nem se darão em casamento; mas serão como os anjos que estão nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 26, 'E quanto aos mortos que ressuscitarão, não lestes no livro de Moisés, como Deus lhe falou com a sarça, dizendo: Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 27, 'Deus não é [Deus] de mortos, mas de vivos. Portanto errais muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 28, 'Então aproximou-se dele um dos escribas, que os havia ouvido discutir. Como ele sabia que [Jesus] havia lhes respondido bem, perguntou-lhe: Qual é o primeiro mandamento de todos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 29, 'E Jesus lhe respondeu: O primeiro de todos os mandamentos é: “Ouve Israel, o Senhor nosso Deus é o único Senhor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 30, 'amarás, pois, ao Senhor teu Deus com todo o teu coração, com toda a tua alma, com todo o teu entendimento, e com todas as tuas forças.” Este é o primeiro mandamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 31, 'E o segundo é semelhante: “Amarás ao teu próximo como a ti mesmo”. Não há outro mandamento maior que estes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 32, 'E o escriba lhe disse: Muito bem, Mestre, com verdade disseste que há um só Deus, e não há outro além dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 33, 'E que amá-lo com todo o coração, com todo o entendimento, com toda a alma, e com todas as forças; e amar ao próximo como a si mesmo, é mais de que todos os holocaustos e sacrifícios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 34, 'Jesus viu que ele havia respondido sabiamente, e disse-lhe: Não estás longe do Reino de Deus. E ninguém mais ousou lhe perguntar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 35, 'E Jesus respondia e dizia, enquanto ensinava no templo: Como os escribas dizem que o Cristo é filho de Davi?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 36, 'Porque o mesmo Davi disse pelo Espírito Santo: Disse o Senhor ao meu Senhor, senta-te à minha direita, até que eu ponha os teus inimigos debaixo dos teus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 37, 'Ora, [se] o próprio Davi o chama de Senhor, como, pois, é so eu filho?E a grande multidão o ouvia de boa vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 38, 'E dizia-lhes em seu ensino: Cuidado com os escribas, que gostam de andar com roupas compridas, das saudações nas praças,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 39, 'das primeiras cadeiras nas sinagogas, e dos primeiros assentos nas ceias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 40, 'que devoram as casas das viúvas, com pretexto de longas orações. Esses receberão mais grave condenação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 41, 'Quando Jesus estava sentado de frente à arca do tesouro, observava como a multidão lançava dinheiro na arca do tesouro; e muitos ricos lançavam muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 42, 'E uma pobre viúva veio, e lançou duas pequenas moedas, de pouco valor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 43, 'Então [Jesus] chamou a si os seus discípulos, e disse-lhes: Em verdade vos digo que esta pobre viúva lançou mais que todos os que lançaram na arca do tesouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 12, 44, 'Porque todos lançaram daquilo que lhes sobra; mas esta, da sua pobreza lançou tudo o que tinha, todo o seu sustento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 1, 'Quando ele estava saindo do templo, um de seus discípulos lhe disse: Mestre, olha que pedras, e que edifícios!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 2, 'Jesus respondeu, dizendo-lhe: Vês estes grandes edifícios? Não será deixada pedra sobre pedra, que não seja derrubada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 3, 'Depois, sentando-se ele no monte das Oliveiras, de frente ao templo, Pedro, Tiago, João, e André perguntaram-lhe à parte:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 4, 'Dize-nos, quando serão essas coisas? E que sinal haverá de quando todas essas coisas se cumprirão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 5, 'E Jesus, respondendo-lhes, começou a dizer: Cuidado! ninguém vos engane;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 6, 'porque muitos virão em meu nome, dizendo: “Sou eu”, e enganarão a muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 7, 'E quando ouvirdes de guerras e de rumores de guerras, não vos perturbeis; porque [assim] deve acontecer; mas ainda não será o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 8, 'Porque nação se levantará contra nação, e reino contra reino, e haverá terremotos em muitos lugares, e haverá fomes e tumultos. Estes serão os princípios das dores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 9, 'Mas cuidai de vós mesmos; porque vos entregarão em tribunais e em sinagogas; sereis açoitados, e sereis levados diante de governadores e reis, por causa de mim, para que lhes haja testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 10, 'Mas antes o Evangelho deve ser pregado entre todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 11, 'Porém, quando vos levarem para vos entregar, não estejais ansiosos antecipadamente do que deveis dizer, nem o planejeis; mas o que naquela hora for dado, isso falai. Porque não sois vós os que falais, mas o Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 12, 'E o irmão entregará ao irmão à morte, e o pai ao filho; e os filhos se levantarão contra os pais, e os matarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 13, 'E sereis odiados por todos por causa do meu nome; mas quem perseverar até o fim, esse será salvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 14, 'E quando virdes a abominação da desolação, que foi dita pelo profeta Daniel, estar onde não deve, (quem lê, entenda), então os que estiverem na Judeia, fujam para os montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 15, 'E quem estiver sobre telhado, não desça para a casa, nem entre para tomar alguma coisa de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 16, 'E quem estiver no campo, não volte atrás, para tomar sua roupa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 17, 'Mas ai das grávidas, e das que amamentarem naqueles dias!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 18, 'Orai, porém, para que a vossa fuga não aconteça no inverno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 19, 'Porque aqueles dias serão de tal aflição, qual nunca foi desde o princípio da criação das coisas, que Deus criou, até agora, nem jamais será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 20, 'E se o Senhor não encurtasse aqueles dias, ninguém se salvaria; mas por causa dos escolhidos, que escolheu, ele encurtou aqueles dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 21, 'Então se alguém vos disser: “Eis aqui o Cristo”; ou “ei-lo ali”, não creiais nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 22, 'Porque se levantarão falsos cristos, e falsos profetas, que farão sinais e prodígios, para enganar, se possível, até os escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 23, 'Vós, porém, tende cuidado; eis que tenho vos dito tudo com antecedência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 24, 'Mas naqueles dias, depois daquela aflição, o sol se escurecerá, e a lua não dará seu brilho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 25, 'as estrelas do céu cairão, e as forças que estão nos céus se abalarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 26, 'Então verão o Filho do homem vir nas nuvens, com grande poder e glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 27, 'Ele então enviará os seus anjos, e ajuntará os seus escolhidos dos quatro ventos, desde a extremidade da terra, até a extremidade do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 28, 'E aprendei a parábola da figueira: Quando o seu ramo já vai ficando tenro, e brota folhas, bem sabeis que o verão já está perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 29, 'Assim também vós, quando virdes suceder estas coisas, sabei que já está perto, às portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 30, 'Em verdade vos digo que não passará esta geração, até que todas estas coisas aconteçam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 31, 'O céu e a terra passarão, mas as minhas palavras em maneira nenhuma passarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 32, 'Porém daquele dia e hora ninguém sabe, nem os anjos que estão no céu, nem o Filho, a não ser somente o Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 33, 'Olhai, vigiai, e orai; porque não sabeis quando será o tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 34, 'Assim como o homem que, partindo-se para fora de sua terra, deixou sua casa, e deu autoridade aos seus servos, e a cada um o seu trabalho, e mandou ao porteiro que vigiasse,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 35, 'assim também vigiai, porque não sabeis quando virá o Senhor da casa; se à tarde, se à meia-noite, se ao cantar do galo, se pela manhã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 36, 'para que ele não venha de repente, e vos ache dormindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 13, 37, 'E as coisas que vos digo, digo a todos: Vigiai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 1, 'E dali a dois dias era a Páscoa, e [a festa] dos pães sem fermento; e os chefes dos sacerdotes, e os escribas buscavam um meio de prendê-lo através de um engano, e o matarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 2, 'Diziam, porém: “Não na festa, para que não aconteça tumulto entre o povo.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 3, 'E estando ele em Betânia, na casa de Simão o Leproso, sentado [à mesa] , veio uma mulher, que tinha um vaso de alabastro, de óleo perfumado de nardo puro, de muito preço, e quebrando o vaso de alabastro, derramou-o sobre a cabeça dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 4, 'E houve alguns que em si mesmos se indignaram, e disseram: “Para que foi feito este desperdício do óleo perfumado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 5, 'Porque isto podia ter sido vendido por mais de trezentos denários, e seria dado aos pobres.” E reclamavam contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 6, 'Porém Jesus disse: “Deixai-a; por que a incomodais? Ela me fez boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 7, 'Porque pobres sempre tendes convosco; e quando quiserdes, podeis lhes fazer bem; porém a mim, nem sempre me tendes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 8, 'Esta fez o que podia; adiantou-se para ungir o meu corpo, para a sepultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 9, 'Em verdade vos digo, que onde quer que em todo o mundo este Evangelho for pregado, também o que esta fez será dito em sua memória.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 10, 'E Judas Iscariotes, um dos doze, foi aos chefes dos sacerdotes, para o entregar a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 11, 'E eles ouvindo, alegraram-se; e prometeram lhe dar dinheiro; e buscava como o entregaria em tempo oportuno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 12, 'E o primeiro dia dos pães sem fermento, quando sacrificavam [o cordeiro da] Páscoa, seus discípulos lhe disseram: “Onde queres que vamos preparar para comerdes a Páscoa?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 13, 'E mandou dois de seus discípulos, e disse-lhes: “Ide à cidade, e um homem que leva um cântaro de água vos encontrará, a ele segui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 14, 'E onde quer que ele entrar, dizei ao senhor da casa: O Mestre diz: Onde está o cômodo onde comerei Páscoa com meus discípulos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 15, 'E ele vos mostrará um grande salão, ornado e preparado; ali fazei os preparativos para nós.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 16, 'E seusdiscípulos saíram, e vieram à cidade, e acharam como havia lhes dito, e prepararam a Páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 17, 'E chegada a tarde, veio com os doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 18, 'E quando se sentaram [à mesa] , e comeram, Jesus disse: “Em verdade vos digo, que um de vós, que está comendo comigo, me trairá.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 19, 'E eles começaram a se entristecer, e a lhe dizer um após outro: “Por acaso sou eu?” E outro: “Por acaso sou eu?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 20, 'Porém ele lhes respondeu: “[É] um dos doze, o que está molhando [a mão] comigo no prato.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 21, 'Em verdade o Filho do homem vai, como está escrito sobre ele; mas ai daquele homem por quem o Filho do homem é traído; bom lhe fosse ao tal homem não haver nascido.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 22, 'E enquanto eles comiam, Jesus tomou o pão; e bendizendo, partiu-o, deu-lhes, e disse: “Tomai, comei, isto é o meu corpo.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 23, 'E tomando o copo, e dando graças, deu-lhes; e todos beberam dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 24, 'E disse-lhes: “Isto é o meu sangue, o do novo testamento, que é derramado por muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 25, 'Em verdade vos digo, que não beberei mais do fruto da vide, até aquele dia, quando o beber novo no Reino de Deus.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 26, 'E depois de cantarem um hino, saíram para o monte das Oliveiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 27, 'E Jesus lhes disse: “Todos vós falhareis comigo esta noite; porque está escrito: Ferirei ao pastor, e as ovelhas serão dispersas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 28, 'Mas depois de eu haver ressuscitado, irei adiante de vós para a Galileia.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 29, 'E Pedro lhe disse: “Ainda que todos falhem, eu não [falharei] .”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 30, 'Jesus lhe disse: “Em verdade te digo, que hoje, nesta noite, antes que o galo cante duas vezes, me negarás três vezes.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 31, 'Mas [Pedro] , insistindo, dizia: “Ainda que me seja necessário morrer contigo, em maneira nenhuma te negarei.” E todos diziam também da mesma maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 32, 'E vieram ao lugar, cujo nome era Getsêmani, e disse a seus discípulos: “Sentai-vos aqui, enquanto eu oro.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 33, 'E tomou consigo Pedro, Tiago, e João, e começou a ficar muito apavorado e angustiado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 34, 'E disse-lhes: “Minha alma totalmente está triste até a morte; ficai-vos aqui, e vigiai.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 35, 'Então ele foi um pouco mais adiante, e prostrou-se em terra. E orou, que se fosse possível, afastasse dele aquela hora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 36, 'E disse: “Aba, Pai, todas as coisas te são possíveis; passa de mim este copo; porém não [se faça] o que eu quero, mas sim o que tu [queres] .”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 37, 'Depois veio de volta, e os achou dormindo; e disse a Pedro: “Simão, estás dormindo? Não podes vigiar uma hora?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 38, 'Vigiai, e orai, para que não entreis em tentação; o espírito em verdade [está] pronto, mas a carne [é] fraca.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 39, 'E depois que se foi novamente, orou, dizendo as mesmas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 40, 'Quando voltou, achou-os outra vez dormindo; porque os olhos deles estavam pesados, e não sabiam o que lhe responder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 41, 'E veio a terceira vez, e disse-lhes: “Ainda estais dormindo e descansando? Basta, chegada é a hora. Eis que o Filho do homem é entregue em mãos dos pecadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 42, 'Levantai-vos, vamos; eis que o que me trai está perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 43, 'E logo, enquanto ele ainda estava falando, veio Judas, que era um dos doze, e com ele uma grande multidão, com espadas e bastões, da parte dos chefes dos sacerdotes, dos escribas, dos anciãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 44, 'E o que o traía lhes tinha dado um sinal comum, dizendo: “Ao que eu beijar, é esse; prendei-o, e levai-o em segurança.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 45, 'E quando veio, logo foi-se a ele, e disse-lhe: “Rabi, Rabi”, e o beijou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 46, 'Então o agarraram, e o prenderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 47, 'E um dos que estavam ali presentes puxou a espada, feriu o servo do sumo sacerdote, e cortou-lhe a orelha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 48, 'Jesus começou a lhes dizer: “Viestes me prender com espadas e bastões, como [se eu fosse] um bandido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 49, 'Todo dia eu estava convosco no templo, ensinando, e não me prendestes; mas [assim se faz] para que as Escrituras se cumpram.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 50, 'Então todos o deixaram, e fugiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 51, 'E certo rapaz o seguia, envolto num lençol sobre o [corpo] nu. E os rapazes o agarraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 52, 'Mas ele largou o lençol, e fugiu deles nu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 53, 'E levaram Jesus ao sumo sacerdote; e ajuntaram-se a ele todos os chefes dos sacerdotes, os anciãos, e os escribas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 54, 'E Pedro o seguiu de longe até dentro do pátio do sumo sacerdote, e ficou sentado com os oficiais, esquentando-se ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 55, 'E os chefes dos sacerdotes, e todo o supremo conselho buscavam [algum] testemunho contra Jesus, para o matarem, e não [o] achavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 56, 'Porque muitos davam falso testemunho contra ele, mas os testemunhos não concordavam entre si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 57, 'E alguns se levantavam e davam falso testemunho contra ele, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 58, '“Nós o ouvimos dizer: Eu derrubarei este templo feito por mãos, e em três dias construirei outro feito não por mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 59, 'E nem assim o testemunho deles era concordante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 60, 'Então o sumo sacerdote levantou-se no meio, e perguntou a Jesus: “Não respondes nada? O que estes testemunham contra ti?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 61, 'Mas ele ficou calado, e nada respondeu. O sumo sacerdote voltou a lhe perguntar: “És tu o Cristo, o Filho daquele que é Bendito?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 62, 'Jesus respondeu: “Eu sou. E vereis o Filho do homem sentado à direita do Poderoso , e vindo com as nuvens do céu.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 63, 'E o sumo sacerdote, rasgando suas roupas, disse: “Para que mais necessitamos de testemunhas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 64, 'Vós ouvistes a blasfêmia. Que vos parece?” E todos o condenaram como culpado de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 65, 'E alguns começaram a cuspir nele, e a cobrir o rosto dele; e a dar-lhe de socos, e dizer-lhe: “Profetiza”. E os oficiais lhe davam bofetadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 66, 'E, enquanto Pedro estava no pátio abaixo, veio uma das servas do sumo sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 67, 'Quando ela viu Pedro, que estava sentado esquentando-se, olhou para ele, e disse: “Também tu estavas com Jesus, o Nazareno.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 68, 'Mas ele negou, dizendo: “Não [o] conheço, nem sei o que dizes.”; e saiu para o alpendre. Então o galo cantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 69, 'A serva o viu outra vez, e começou a dizer aos que ali estavam: “Este é um deles”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 70, 'Mas ele o negou de novo. E pouco depois, outra vez os que ali estavam disseram a Pedro: “Verdadeiramente tu és um deles; pois também és galileu”, e a tua fala é semelhante”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 71, 'Então ele começou a amaldiçoar e a jurar, [dizendo] : “Não conheço esse homem de quem dizeis.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 14, 72, 'O galo cantou a segunda vez. E Pedro se lembrou da palavra que Jesus havia lhe dito: “Antes que o galo cante duas vezes, tu me negarás três vezes.” Então ele retirou-se dali e chorou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 1, 'E logo ao amanhecer, os chefes dos sacerdotes tiveram uma reunião com os anciãos, com os escribas, e com todo o supremo conselho; e, amarrando Jesus, levaram [-no] e [o] entregaram a Pilatos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 2, 'E Pilatos lhe perguntou: És tu o Rei dos Judeus? E ele lhe respondeu: Tu o dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 3, 'E os chefes dos sacerdotes o acusavam de muitas coisas, porém ele nada respondia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 4, 'E outra vez Pilatos lhe perguntou: Não respondes nada? Olha quantas [coisas] testemunham contra ti!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 5, 'Mas Jesus nada mais respondeu, de maneira que Pilatos ficou surpreso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 6, 'Na festa, [Pilatos] lhes soltava um preso, qualquer um que pedissem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 7, 'E havia um chamado Barrabás, preso com [outros] revoltosos, que numa rebelião havia cometido uma morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 8, 'E a multidão, gritando, começou a pedir, como sempre lhes havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 9, 'E Pilatos lhes respondeu: Quereis que eu vos solte o Rei dos Judeus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 10, '(Porque ele sabia que os chefes dos sacerdotes haviam o entregue por inveja).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 11, 'Mas os chefes dos sacerdotes incitaram a multidão, para que, em vez disso, lhes soltasse Barrabás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 12, 'E Pilatos, respondendo, disse-lhes outra vez: Que, pois, quereis que eu faça com aquele a quem chamais Rei dos Judeus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 13, 'E eles voltaram a clamar: Crucifica-o!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 14, 'Mas Pilatos lhes disse: Por quê? Que mal ele fez? E eles gritavam ainda mais: Crucifica-o!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 15, 'Então Pilatos, querendo satisfazer à multidão, soltou-lhes Barrabás; e entregou Jesus açoitado, para que fosse crucificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 16, 'E os soldados o levaram para o pátio, que é o pretório; e convocaram toda a tropa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 17, 'E o vestiram de púrpura; teceram uma coroa de espinhos, e puseram nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 18, 'E começaram a saudá-lo: Viva! Ó Rei dos Judeus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 19, 'E feriram a sua cabeça com uma cana, cuspiram nele, e, ajoelhados, o adoraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 20, 'Quando o escarneceram, despiram-lhe a púrpura, vestiram-no com as suas próprias roupas, e o levaram afora, para o crucificarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 21, 'E forçaram um Simão cireneu, que estava passando, vindo do campo, o pai de Alexandre e de Rufo, para que levasse sua cruz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 22, 'E o levaram ao lugar de Gólgota, que traduzido é: o lugar da caveira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 23, 'E ofereceram-lhe a beber vinho misturado com mirra; mas ele não o tomou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 24, 'E havendo o crucificado, repartiram a roupas dele, lançando-lhes sortes, para o que cada um levaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 25, 'Era a hora terceira, e o crucificaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 26, 'E a descrição de sua acusação estava acima escrita: O REI DOS JUDEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 27, 'E crucificaram com ele dois ladrões, um à sua direita, e outro à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 28, 'E cumpriu-se a Escritura que diz: E foi contado com os malfeitores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 29, 'E os que passavam blasfemavam dele, balançando suas cabeças, e dizendo: Ah! tu que derrubas o templo, e em três dias o edificas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 30, 'salva a ti mesmo, e desce da cruz!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 31, 'E da mesma maneira também os chefes dos sacerdotes, com os escribas, diziam aos outros, escarnecendo: Ele salvou a outros, a si mesmo não pode salvar!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 32, 'Que o Cristo, o Rei de Israel, desça agora da cruz, para que o vejamos, e creiamos! Os que estavam crucificados com ele também o insultavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 33, 'E vinda a hora sexta, vieram trevas sobre toda a terra, até a hora nona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 34, 'E na hora nona, Jesus exclamou em alta voz: ELOÍ, ELOÍ, LAMÁ SABACTÂNI, que traduzido é: Deus meu, Deus meu, por que me desamparaste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 35, 'E alguns dos que ali estavam, quando ouviram, disseram: Eis que ele está chamando Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 36, 'E um correu, encheu de vinagre uma esponja; e pondo-a em uma cana, dava-lhe de beber, dizendo: Deixai, vejamos se Elias virá tirá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 37, 'E Jesus bradou em grande voz, então expirou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 38, 'E o véu do Templo se rasgou em dois do alto abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 39, 'E o centurião que estava ali diante dele, vendo que havia expirado bradando assim, disse: Verdadeiramente este homem era Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 40, 'E também estavam ali [algumas] mulheres olhando de longe, entre as quais estava também Maria Madalena, e Maria (mãe de Tiago o menor e de José), e Salomé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 41, 'as quais também, quando ele estava na Galileia, o seguiam, e o serviam; e outras muitas, que haviam subido com ele a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 42, 'E quando já vinha o final da tarde, porque era a preparação, que é o dia antes de sábado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 43, 'Veio José de Arimateia, honrado membro do conselho, que também esperava o Reino de Deus, e com ousadia foi a Pilatos, e pediu o corpo de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 44, 'Pilatos se surpreendeu de que já fosse morto. E chamou a si o centurião, e perguntou-lhe se já era morto já havia muito tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 45, 'Quando ele recebeu a explicação do centurião, deu o corpo a José,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 46, 'o qual comprou um lençol fino, e tirando-o [da cruz] , envolveu-o no lençol fino. Em seguida, ele o pôs num sepulcro escavado em uma rocha, e rolouuma pedra à porta do sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 15, 47, 'Maria Madalena e Maria [mãe] de José olharam onde o puseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 1, 'Havendo passado o sábado, Maria Madalena, e Maria [mãe] de Tiago, e Salomé, compraram especiarias, para irem o ungir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 2, 'E de manhã muito cedo, o primeiro dia da semana, vieram ao sepulcro, ao nascer do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 3, 'E diziam umas às outras: Quem rolará para nós a pedra da porta do sepulcro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 4, 'Pois era muito grande. E quando observaram, viram que já a pedra estava havia sido rolada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 5, 'e entrando no sepulcro, viram um rapaz sentado à direita, vestido com uma roupa comprida branca; e elas se espantaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 6, 'Mas ele lhes disse: Não vos espanteis. Vós buscais a Jesus Nazareno crucificado. Ele já ressuscitou, não está aqui. Eis aqui o lugar onde o puseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 7, 'Porém ide, dizei a seus discípulos e a Pedro, que ele vai adiante de para a Galileia; ali o vereis, como ele vos disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 8, 'Então elas, saindo apressadamente, fugiram do sepulcro, porque temor e espanto as haviam tomado; e não disseram nada a ninguém, porque tinham medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 9, 'E havendo ressuscitado pela manhã, no primeiro [dia] da semana, [Jesus] apareceu primeiramente a Maria Madalena, da qual havia expulsado sete demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 10, 'Ela se foi, e anunciou aos que estiveram com ele, que estavam tristes e chorando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 11, 'Quando ouviram que ele estava vivo, e que havia sido visto por ela, eles não creram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 12, 'E depois ele apareceu em outra forma a dois deles, que estavam indo pelo caminho ao campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 13, 'E estes foram anunciar aos outros; mas também não creram neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 14, 'Finalmente ele apareceu aos onze, estando eles sentados juntos; e repreendeu pela incredulidade e dureza de coração deles, por não terem crido nos que já o haviam visto ressuscitado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 15, 'E disse-lhes: Ide por todo o mundo, pregai o Evangelho a toda criatura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 16, 'Quem crer e for batizado será salvo; mas quem não crer será condenado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 17, 'E estes sinais seguirão aos que crerem: em meu nome expulsarão demônios; falarão novas línguas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 18, 'pegarão serpentes com as mãos; e se beberem algo mortífero, não lhes fará dano algum; porão as mãos sobre os enfermos, e sararão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 19, 'Então o Senhor, depois de haver lhes falado, foi recebido acima no céu, e sentou-se à direita de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 16, 20, 'E eles saíram e pregaram por todas as partes, [com] o Senhor operando com eles, e confirmando a palavra com os sinais que se seguiam. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 1, 'Como muitos empreenderam pôr em ordem o relato das coisas que entre nós se cumpriram,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 2, 'conforme os que [as] viram que desde o princípio, e foram servidores das palavra, nos transmitiram,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 3, 'pareceu-me bom que também eu, que tenho me informado com exatidão desde o princípio, escrevesse-as em ordem a ti, caríssimo Teófilo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 4, 'para que conheças a certeza das coisas de que foste ensinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 5, 'Houve nos dias de Herodes, rei da Judeia, um sacerdote chamado Zacarias, da ordem de Abias; sua mulher das filhas de Arão, e o seu nome era Isabel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 6, 'E ambos eram justos diante de Deus; andavam sem repreensão em todos os mandamentos e preceitos do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 7, 'Mas não tinham filho, porque Isabel era estéril, e ambos tinham idade avançada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 8, 'E aconteceu que, quando ele fazia o trabalho sacerdotal diante de Deus, na ordem da sua turma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 9, 'conforme o costume do sacerdócio, foi sorteado a entrar no santuário do Senhor para oferecer o incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 10, 'E toda a multidão do povo estava fora orando, à hora do incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 11, 'Então um anjo do Senhor lhe apareceu em pé, à direita do altar do incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 12, 'Quando Zacarias [o] viu, perturbou-se, e o medo o tomou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 13, 'Mas o anjo lhe disse: Zacarias, não temas, pois a tua oração foi ouvida. E Isabel, tua mulher, dará à luz um filho, e lhe porás o nome de João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 14, 'E terás prazer e alegria, e muitos se alegrarão do seu nascimento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 15, 'pois ele será grande diante do Senhor, e não beberá vinho nem bebida alcoólica, e será cheio do Espírito Santo, já desde o ventre da sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 16, 'E converterá muitos dos filhos de Israel ao Senhor seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 17, 'E irá adiante dele no espírito e virtude de Elias, para converter os corações dos pais aos filhos, e os rebeldes à prudência dos justos; a fim de preparar um povo pronto ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 18, 'Então Zacarias disse ao anjo: Como terei certeza disso? Pois sou velho, e a minha mulher de idade avançada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 19, 'O anjo lhe respondeu: Eu sou Gabriel, que fico presente diante de Deus, e fui enviado para te falar e te dar estas boas notícias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 20, 'Eis que ficarás mudo, e não poderás falar até o dia em que essas coisas aconteçam, porque não creste nas minhas palavras, que se cumprirão no devido tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 21, 'E o povo estava esperando Zacarias, e se surpreenderam de que ele demorava no santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 22, 'Quando ele saiu, não conseguia lhes falar; e entenderam que havia tido alguma visão no santuário. Ele lhes fazia gestos, e continuou mudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 23, 'E sucedeu que, terminados os dias do seu serviço, voltou à sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 24, 'E depois daqueles dias Isabel, sua mulher, Isabel, engravidou-se, e por cinco meses se escondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 25, 'Pois isto o Senhor me fez nos dias em que ele [me] observou, para acabar a minha humilhação entre as pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 26, 'E no sexto mês o anjo Gabriel foi enviado por Deus a uma cidade da Galileia, chamada Nazaré,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 27, 'a uma virgem prometida em casamento com um homem chamado José, da descendência de Davi; e o nome da virgem era Maria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 28, 'O anjo entrou onde ela estava, e disse: Alegra-te, agraciada; o Senhor [é] contigo, bendita [és] tu entre as mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 29, 'Quando ela [o] viu, perturbou-se muito por suas palavras, e se perguntava que saudação seria esta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 30, 'Então o anjo lhe disse: Maria, não temas, porque encontraste graça diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 31, 'E eis que em teu ventre conceberás, darás à luz um filho, e chamarás o seu nome de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 32, 'Ele será grande, e será chamado Filho do Altíssimo; e o Senhor Deus lhe dará o trono de Davi, seu ancestral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 33, 'E reinará eternamente na casa de Jacó; o seu reino não terá fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 34, 'Maria disse ao anjo: Como será isso? Pois não conheço intimamente homem algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 35, 'O anjo lhe respondeu: O Espírito Santo virá sobre ti, e o poder do Altíssimo te cobrirá com a sua sombra. Por isso o Santo que nascerá de ti será chamado Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 36, 'E eis que Isabel, tua prima, também está grávida de um filho na sua velhice; e este é o sexto mês para a que era chamada de estéril.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 37, 'Pois para Deus nada será impossível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 38, 'Então Maria disse: Eis aqui a serva do Senhor; cumpra-se em mim conforme a tua palavra. E o anjo ausentou-se dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 39, 'E naqueles dias, Maria levantou-se, e foi apressada à região montanhosa, a uma cidade de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 40, 'Ela entrou na casa de Zacarias, e cumprimentou Isabel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 41, 'E aconteceu que, quando Isabel ouviu o cumprimento de Maria, a criança saltou no seu ventre, e Isabel foi cheia do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 42, 'Então exclamou em alta voz: Bendita [és] tu entre as mulheres, e bendito [é] o fruto do teu ventre!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 43, 'Como me acontece isto, que a mãe de meu Senhor venha a mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 44, 'Pois eis que, quando a voz do teu cumprimento chegou aos meus ouvidos, a criança saltou de alegria no meu ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 45, 'E bendita é a que creu, pois as coisas que da parte do Senhor lhe foram ditas se cumprirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 46, 'Então Maria disse: A minha alma engrandece ao Senhor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 47, 'e o meu espírito se alegra em Deus meu Salvador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 48, 'Porque ele observou a humilde condição da sua serva; pois eis que desde agora todas as gerações me chamarão bendita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 49, 'Pois o Poderoso me fez grandes coisas; e santo [é] o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 50, 'E a sua misericórdia é de geração em geração sobre os que o temem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 51, 'Com o seu braço manifestou poder; dispersou os soberbos no pensamento dos seus corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 52, 'Derrubou os poderosos dos tronos, e elevou os humildes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 53, 'Encheu de bens aos famintos, e despediu vazios os ricos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 54, 'Auxiliou ao seu servo Israel, lembrando-se da [sua] misericórdia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 55, 'como falou aos nossos ancestrais, a Abraão, e à sua descendência, para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 56, 'Maria esteve com ela por quase três meses; então voltou para sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 57, 'E completou-se à Isabel o tempo de dar à luz, e teve um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 58, 'Os seus vizinhos e parentes ouviram que o Senhor havia feito a ela grande misericórdia, e alegraram-se com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 59, 'E aconteceu que ao oitavo dia vieram circuncidar o menino, e o chamavam Zacarias, do nome do seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 60, 'E sua mãe respondeu: Não, porém será chamado João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 61, 'E disseram-lhe: Ninguém há entre os teus parentes que se chame deste nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 62, 'E perguntaram por gestos ao seu pai como queria que lhe chamassem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 63, 'Ele pediu uma tábua, e escreveu: O seu nome é João. E todos se surpeenderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 64, 'E logo a sua boca se abriu, e a sua língua se [soltou] ; e voltou a falar, louvando a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 65, 'E veio temor sobre todos os seus vizinhos; e em toda a região montanhosa da Judeia todas essas coisas foram divulgadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 66, 'E todos os que ouviam, guardavam em seus corações, dizendo: Quem será este menino? E a mão do Senhor estava com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 67, 'E Zacarias, seu pai, foi cheio do Espírito Santo, e profetizou, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 68, 'Bendito [seja] o Senhor Deus de Israel, porque visitou e redimiu o seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 69, 'E nos levantou uma poderosa salvação na casa de seu servo Davi,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 70, 'como falou pela boca dos seus santos profetas, desde o princípio do mundo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 71, 'Que [nos] livraria dos nossos inimigos e da mão de todos os que nos odeiam,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 72, 'para manifestar misericórdia aos nossos ancestrais, e se lembrar do seu santo pacto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 73, 'do juramento que fez a Abraão, nosso ancestral;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 74, 'de nos conceder que, libertos da mão dos nossos inimigos, o serviríamos sem temor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 75, 'em santidade e justiça diante dele, todos os dias da nossa vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 76, 'E tu, menino, serás chamado profeta do Altíssimo; porque irás adiante da face do Senhor, para preparar os seus caminhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 77, 'para dar a seu povo conhecimento da salvação, na remissão de seus pecados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 78, 'por causa da profunda misericórdia do nosso Deus, pela qual o raiar da manhã nos visitou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 79, 'para iluminar os que estão sentados nas trevas e sombra de morte; a fim de guiar os nossos pés pelo caminho da paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 1, 80, 'E o menino crescia e se fortalecia em espírito. E esteve nos desertos até o dia em que se mostrou a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 1, 'E aconteceu naqueles dias que saiu um decreto da parte de César Augusto, para que todo a terra se registrasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 2, '(Esse primeiro censo foi feito quando Quirino era o governador da Síria.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 3, 'E todos foram se registrar, cada um à sua própria cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 4, 'E José também subiu da Galileia, da cidade de Nazaré à Judeia, à cidade de Davi, que se chama Belém; (porque [ele] era da casa e família de Davi.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 5, 'Para se registrar com Maria, sua mulher, com ele prometida em casamento, que estava grávida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 6, 'E aconteceu que, enquanto eles ali, completaram-se os dias em que ela havia de dar à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 7, 'E deu à luz seu filho primogênito, e o envolveu em panos, e o deitou numa manjedoura; porque não havia lugar para eles na hospedaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 8, 'E naquela mesma localidade havia pastores que estavam no campo, e vigiavam o seu rebanho durante as vigílias da noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 9, 'E eis que um anjo do Senhor lhe apareceu, e a glória do Senhor os cercou de resplendor. Então tiveram grande temor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 10, 'E o anjo lhes disse: Não temais; pois eis que vos dou notícias de grande alegria, que será para todo o povo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 11, 'que hoje na cidade de Davi vos nasceu o Salvador, que é Cristo, o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 12, 'E isto vos será por sinal: achareis o menino envolto em panos, deitado numa manjedoura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 13, 'E no mesmo instante apareceu com o anjo uma multidão de exércitos celestiais, louvando a Deus, e dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 14, 'Glória nas alturas a Deus, paz na terra, [e] aos seres humanos boa vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 15, 'E aconteceu que, quando os anjos se ausentaram deles para o céu, os pastores disseram uns aos outros: Vamos, pois, até Belém, e vejamos isso que aconteceu, e o Senhor nos informou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 16, 'Então foram apressadamente, e acharam Maria, e José, e o menino deitado na manjedoura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 17, 'Quando [o] viram, contaram o que lhes havia sido dito sobre o menino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 18, 'E todos os que ouviram se admiraram com o que os pastores lhes diziam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 19, 'Mas Maria guardava todas essas palavras, considerando [-as] no seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 20, 'Os pastores voltaram glorificando e louvando a Deus por tudo o que haviam ouvido e visto, como lhes havia sido dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 21, 'Quando se completaram os oito dias para circuncidar o menino, foi chamado o seu nome Jesus, o qual havia sido posto pelo anjo antes que fosse concebido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 22, 'E quando se completaram os dias da purificação dela, segundo a Lei de Moisés, o levaram a Jerusalém, para o apresentarem ao Senhor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 23, 'conforme o que está escrito na Lei do Senhor: Todo macho primogênito será consagrado ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 24, 'E para darem a oferta segundo o que se diz na Lei do Senhor: um par de rolinhas ou dois pombinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 25, 'E eis que havia em Jerusalém um homem de nome Simeão; e esse homem era justo e devoto, e esperava a consolação de Israel; e o Espírito Santo estava sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 2, 26, 'E havia lhe sido revelado pelo Espírito Santo que ele não veria a morte antes de ter visto o Cristo do Senhor.')
